def jamesJoinedIndex (s t : JamesPath) : Fin (s.length + t.length + 2) → ℕ :=
  fun i => if hi : i.val ≤ s.length then s.index ⟨i.val, by omega⟩
    else t.index ⟨i.val - (s.length + 1), by have := i.isLt; omega⟩

